CREATE TABLE MATRNAMSTS_OLD AS SELECT * FROM MATRNAMSTS;
DROP TABLE MATRNAMSTS CASCADE CONSTRAINT PURGE;

CREATE TABLE MATRNAMSTS
(
    FACTORY                     VARCHAR2(10)    DEFAULT (' ')   NOT NULL,
    ATTR_TYPE                   VARCHAR2(20)    DEFAULT (' ')   NOT NULL,               
    ATTR_NAME                   VARCHAR2(100)   DEFAULT (' ')   NOT NULL,
    ATTR_KEY                    VARCHAR2(30)    DEFAULT (' ')   NOT NULL,               
    KEY_HIST_SEQ                NUMBER(10)      DEFAULT (0)     NOT NULL,                
    ATTR_VALUE                  VARCHAR2(1000)  DEFAULT (' ')   NOT NULL,               
    NULL_FLAG                   CHAR(1)         DEFAULT (' ')   NOT NULL,
    LAST_TRAN_TIME              VARCHAR2(14)    DEFAULT (' ')   NOT NULL,
    LAST_ACTIVE_HIST_SEQ        NUMBER(10)      DEFAULT (0)     NOT NULL,
    LAST_HIST_SEQ               NUMBER(10)      DEFAULT (0)     NOT NULL 
) TABLESPACE MESPLUS_DATA_TS;

ALTER TABLE MATRNAMSTS
ADD CONSTRAINT MATRNAMSTS_PK PRIMARY KEY
(
    FACTORY,
    ATTR_TYPE,
    ATTR_NAME,
    ATTR_KEY
) USING INDEX TABLESPACE MESPLUS_IDX_TS;

CREATE INDEX MATRNAMSTS_IDX_1 ON MATRNAMSTS
(
    FACTORY,
    ATTR_KEY,
    ATTR_TYPE,
    ATTR_NAME
) TABLESPACE MESPLUS_IDX_TS;

SELECT 
    FACTORY              ,
    ATTR_TYPE            ,
    ATTR_NAME            ,
    ATTR_KEY             ,
    KEY_HIST_SEQ         ,
    ATTR_VALUE           ,
    ' '                  ,
    LAST_TRAN_TIME       ,
    LAST_ACTIVE_HIST_SEQ ,
    LAST_HIST_SEQ
FROM MATRNAMSTS_OLD);

DECLARE
     V_MATRNAMHIS       MATRNAMHIS%ROWTYPE;
     V_LAST_HIST_SEQ    NUMBER(10);
BEGIN
	 FOR REC IN (
        SELECT FACTORY, ATTR_TYPE, ATTR_NAME, ATTR_KEY, MAX(HIST_SEQ) AS HIST_SEQ 
        FROM MATRNAMHIS
        WHERE HIST_DEL_FLAG = ' '
        GROUP BY FACTORY, ATTR_TYPE, ATTR_NAME, ATTR_KEY
	 )
     LOOP
        BEGIN
            SELECT * 
            INTO V_MATRNAMHIS
            FROM MATRNAMHIS
            WHERE FACTORY = REC.FACTORY
                AND ATTR_TYPE = REC.ATTR_TYPE
                AND ATTR_NAME = REC.ATTR_NAME
                AND ATTR_KEY = REC.ATTR_KEY
                AND HIST_SEQ = REC.HIST_SEQ;
            
            SELECT MAX(HIST_SEQ) 
            INTO V_LAST_HIST_SEQ
            FROM MATRNAMHIS
            WHERE FACTORY = REC.FACTORY
                AND ATTR_TYPE = REC.ATTR_TYPE
                AND ATTR_NAME = REC.ATTR_NAME
                AND ATTR_KEY = REC.ATTR_KEY;

            IF V_MATRNAMHIS.NULL_FLAG = 'Y' THEN
                    V_MATRNAMHIS.FACTORY        ,
                    V_MATRNAMHIS.ATTR_TYPE      ,
                    V_MATRNAMHIS.ATTR_NAME      ,
                    V_MATRNAMHIS.ATTR_KEY       ,
                    V_MATRNAMHIS.KEY_HIST_SEQ   ,
                    V_MATRNAMHIS.ATTR_NEW_VALUE ,
                    V_MATRNAMHIS.NULL_FLAG      ,
                    V_MATRNAMHIS.TRAN_TIME      ,
                    V_MATRNAMHIS.HIST_SEQ       ,
                    V_LAST_HIST_SEQ);
            END IF;
            
            EXCEPTION
                WHEN OTHERS THEN  -- catches all 'no data found' errors
                    DBMS_OUTPUT.PUT_LINE (' exception no_data_found' );
        END;
     END LOOP;
END;
/


